INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1004308-me323', 'stk-user4394', 'ME 323', 'info', '{"desc": "مثل اسلوب الــ me 216 ماده تعتد على الحفظ بشكل اساسي\n\nذاكر الكتاب من اول يوم ولا تفوت ولا يوم عشان لايتراكم عليك\n\nالكتاب لابأس فيه بس الماتريل طويل جدا", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-323-manufacturing-lab/120748/2", "user": "user4394", "ts": 1331387204000, "tid": 120748, "pn": 2}}', 1331387204000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1032641-me323', 'stk-user5643', 'ME 323', 'info', '{"desc": "من احلى لابات التخصص\n\nلاب ممتع و سهل جدا … اسهل و احلى من لاب 215 ( او 217 )\n\nيمكن 70 بالميه من التجارب مافيها حسابات و لاتحتاج اكسل\n\nبس تحط صور و تكتب وش سوييت\n\nو تطلع بسرعه من الاب بعد", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-323-manufacturing-lab/120748/4", "user": "user5643", "ts": 1336224893000, "tid": 120748, "pn": 4}}', 1336224893000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user5712-me323', 'stk-user5712', 'ME 323', 'doc', '{"docs": [{"id": "stk-dr-f98241", "n": "Dr. B. Jabbar Abdul Aleem", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ياليت معلومات أكثر عن me 323 اللي هي لاب ME 206 سابقاً\nوخصوصاً من ناحية القريد والتصحيح ، لأنها صارت مادة لحالها ولها قريد منفصل", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p972618-me323", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-abdul-aleem-b-jabbar/98241/3", "user": "user5712", "ts": 1327323738000, "tid": 98241, "pn": 3}}, {"id": "stk-dr-f98206", "n": "Dr. Muzafferuddin Mahmood", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "me 323 - 112\n\nأطيب مدرس مر علي في هالجامعة\n\nالتحضير :\nهو ما يجي إلا بعد ربع ساعة ، يحضر في البداية و في النهاية علشان ما أحد يفوته التحضير.\nماعنده مشكلة مع التأخير ، وما عنده مشكلة مع الميك أب (تقدر تحضر أي لاب عنده أو عند غيره بس لازم تكون نفس التجربة).\n\nطريقة الشرح :\nطبعاً هذي المادة لاب فقط ، وكان شرحه فيها عادي.\nأصلاً حتى مادة اللكتشر (me 322) ما في مدرس يشرحها عدل ، كل الطلاب يعتمدوا على الكتاب ، وحتى لو “مظفر الدين محمود” يدرس لكشر بنزل عنده لأن شرحه يعتبر ماهوب شين.\n\nالكويزات :\nما عطانا ولا كويز.\n\nالفاينلات :\nسهل مررررة ، جاب لنا خيارات 25 سؤال ، وكل الأسئلة صور وأسماء معدات وشغلات سهلة\nوتقدر تشوف إجابات الفصل كله ، لأنه يسوي روحه ما يشوف الطلاب وهم يغشوا.\n\nتسليم الريبورت:\nيعطي الطلاب مهلة أسبوع لتسليم الريبورت إذا كان عندهم مياجر ، لكن من طيبته تقدر تسلم الريبورت في أي وقت خلال السمستر ، ولا يخصم ولا شيء على التأخير.\nحتى وأحنا في اختبار الفاينال قال للطلاب اللي عندهم ريبورتات ناقصة أنهم يقدروا يسلموهم ألحين (وقت الفاينلات) ، واللي عنده غياب قال له دبر لك إكسكسيوز.\n\nدرجات الريبورتات:\nعنده قاعدة إنه ما يعطي ولا طالب 20/20 ، لكنه في أسوأ الحالات يعطيك 17/20 ويقول لك عيد الريبورت وأخليها لك 18/20 أو 19/20\nفي الغالب إذا ما عندك ولا خطأ يعطيك 19/20 وإذا عندك خطأ بسيط يعطيك 18/20 ، ولو ما عجبتك الدرجة تقدر تعيد الريبورت ويزيدك عليها.\n\nالقريد النهائي:\na+++++++++ وأنصح أي واحد يبغى يرتاح نفسياً أنه ينزل عنده\n\nإضافات :\nهالمدرس يحرجك بطيبته وأخلاقه الحلوة ، حتى إذا وأنت قاعد تكلمه تحصله يربت على كتفك يعني كأنه يقول لك “لاتشيل هم ياولدي”.\nوأنا أنصح أنك تنزل معه حتى في اللكتشر لأنه هو دكتور وله خبرة في القسم.\nوفي النهاية ضبطنا في الفاينال قريد ، عطى كثير منا a , a+\n\nمن أفضل دكاترة هالقسم وأطيبهم", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1047615-me323", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/muzafferuddin-mahmood/98206/9", "user": "user5712", "ts": 1338311193000, "tid": 98206, "pn": 9}}]}', 1327323738000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-trad-me323', 'stk-trad', 'ME 323', 'doc', '{"docs": [{"id": "stk-dr-f98206", "n": "Dr. Muzafferuddin Mahmood", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME323-202\n(Online)\n\nالتحضير :\nيحضر وسط الكلاس بالاسماء وماعنده مشكلة تتاخر او تسوي ميك اب اي يوم.\n\nطريقة الشرح :\nشرح تسليكي للي في السلايدات بعدها يورينا مقاطع للتجربة وخلاص\nالكويزات :\nمافيه\nالمياجر: كومن\nالفاينلات :كومن\n\nالقريد النهائي:+B\n\nالصوت: لهجة هندية ومفهوم نوع ما\n\nإضافات :\nالدكتور تحسه مغصوب على اللاب يدرسك بدون نفس, الشي الجميل فيه هو ان اللاب خفيييف جدا معه وما يتعدا الساعة غالبا. الرجال متعاون كثير من ناحية التحضير. المادة الصراحة ماكانت مفيدة جدا بحكم انها عملي والوضع كان اونلاين فكان كل شي تسليك. طبعا فيه شي ثاني جميل فيه انه مايدقق في الريبورتات من ناحية النسخ وما النسخ لدرجة انك يمكن تنسخ ريبورت كامل ولا يقولك شي بس طبعا مستحيل يعطيك 20 في اي ريبورت مدري ليش. الدكتور مزاجي نوع ما ومايرد عالايميلات واذا رد عليك يرد رد تسيلكي جدا يعني طبيعي تكتب له عشر سطور ويرد عليك بكلمة وحدة او كلمتين. قهرني والله نهاية الترم ماعطاني القريد اللي كنت ابغاه مع اني كنت قريب منه واساسا تقيمه لك غير واضح.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1530038-me323", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/muzafferuddin-mahmood/98206/19", "user": "Trad", "ts": 1621639504000, "tid": 98206, "pn": 19}}]}', 1621639504000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-moh_ammed-me323', 'stk-moh_ammed', 'ME 323', 'doc', '{"docs": [{"id": "stk-dr-f98206", "n": "Dr. Muzafferuddin Mahmood", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME 323 - Term 222\n\nالتحضير: ياخذه بعد بدء المحاضرة بعشر دقايق تقريبا بس مو متشدد فيه،، فيه طلاب يتأخرون ويحضرهم.\n\nالشرح: مش ولابد.\n\nإضافات:\n- الدكتور أخلاقه جدا عالية ومتساعد في الديد لاينز والأشياء هذي.\n- المادة فيها ريبورتات وفاينل. الفاينل تقدر تتطلع على السلايدات وبتكفيك بنسبة جيدة، الفاينل كان خيارات، صح وخطأ، املأ الفراغ (حسب ما أذكر).\n- الدكتور جيد في اللاب وحبيب بس ما أعرف عن وضعه في اللكتشر (أحسه ماينفع مرة).\n\nالقريد النهائي: B+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1536773-me323", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/muzafferuddin-mahmood/98206/20", "user": "Moh_ammed", "ts": 1687246105000, "tid": 98206, "pn": 20}}]}', 1687246105000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-dyaa94-me323', 'stk-dyaa94', 'ME 323', 'doc', '{"docs": [{"id": "stk-dr-f98208", "n": "Dr. Mohammed Yaqub", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "152 - me323\n\nمادري وش وضعه ب210 بسسسس لاتفوته في اللابات…\n\nيعطيك الزبده في الشرح…الريبورتات سههههالات الشباب في السكاشن الثانيه يكتبوا تقرير كامل كل اسبوع انترو انالسس كنكلوجن…واحنا يعقوب عشر اسئلة سهله يمديك تحلها قبل الكلاس بساعه هههههه…\n\nطبعا الفاينل كومن وسهالات…والاسئلة اللي يعطي للريبورت كل اسبوع جدا مفيدين في الفاينل…\n\nفي النهاية عطاني فوق القريد اللي استحق…شكرا لك مستر يعقوب…", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1449715-me323", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammed-yaqub/98208/8", "user": "Dyaa94", "ts": 1463681826000, "tid": 98208, "pn": 8}}]}', 1463681826000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-m_nd_m-me323', 'stk-m_nd_m', 'ME 323', 'doc', '{"docs": [{"id": "stk-dr-f98225", "n": "Dr. Mohammad Anis", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME323 - T171\n\nالتحضير : يحضر نهاية اللكتشر و إذا جيت متأخر مرة يمشيها لك، و إذا عدتها ممكن يوبخك و ممكن يقولك إطلع برا إذا زودتها\nبالنسبة للميك أب الدكتور يفضل إنك تحضر بسكشنك، لكنه حبيب إذا عندك ظرف مثلًا ولا شي كلمه من بدري و بيسمح لك تحضر\n\nطريقة الشرح : يستخدم سلايدات يشرحها و يستخدم مقاطع فيديو لتوضيح بعض المفاهيم، بشكل عام شرحه عادي (يجيب النوم شوي)\n\nالكويزات : لا يوجد كويزات\nأما بالنسبة للريبورتات فأغلبها كانت بسيطة و قصيرة (تاخذ ساعة تقريبًا)، يعني إفتح سلايداته و دور على الأجوبة و تصحيحه لا بأس\n\nالمياجر: لا يوجد\n\nالفاينلات : كومون\n\nالقريد النهائي: بالنسبة لتقييمي للدكتور فأتركه لكم\nبالنسبة للفاينل قريد الأفرج عنده B + ما قالنا كم كان الأفرج + شخصيًا جبت 89 و طلعت A\nتوزيع الدرجات 70% ريبورت، و 30% فاينل\n\nالصوت: عنده أكسنت لكن واضح مسموع\n\nإضافات :\n\nحبيب و محترم جدًا\nخدوم بالمكتب مستعد يشرحلك الريبورت كامل\nسريع بالتصحيح\nتعاون معنا في بعض الأسابيع بموعد تسليم الريبورتات\n\nشرحه يجيب النوم شوي (العتب على نظام اللابات عندنا بالقسم)\nما أرسلنا سيلابس طوال السمستر للأسف ماندري عن اللابات ولا عن توزيع القريدات ولا شي إلا على آخر السمستر\nكان يطلب نحل الريبورت بخط اليد، يصير صعب ترجع للريبورت\n\nمجموعة من السلايدات + المانيوال رفعتها على الريسورسيز\n\nو إن شاء الله ما نسيت شي\nAre you getting me؟ (لن يفهمها إلا من درس عنده 🤠)", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1486901-me323", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-mohammad-anis/98225/19", "user": "M_nd_m", "ts": 1517165746000, "tid": 98225, "pn": 19}}]}', 1517165746000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-omar_ali_bajabaau-me323', 'stk-omar_ali_bajabaau', 'ME 323', 'doc', '{"docs": [{"id": "stk-dr-f98225", "n": "Dr. Mohammad Anis", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME 323 - 201\n(Online)\n\nالتحضير: مايحضر ونادرا ما ينادي اسماء معينة، اتوقع الي غياباتهم كثيرة.\n\nطريقة الشرح : من السلايدات وشرحه عبارة عن قراءة من السلايدات مع شوية تفصيل بسيط من عنده بس صراحة شرحه سيئ وصعب تفهم ويجيب النوم. انا شخصيا حاولت افهم واركز ماقدرت اكمل الا وجاني نوم ((هذا وانا معايا كاسة قهوة)).\n\nالتصحيح: الريبورت كان عبارة عن اسئلة وتجاوب عليها فقط واجوبتها تلاقيها في السلايدات نسخ لصق. وهذا الي عجبني فيه صراحة. تصحيحه للريبورت حلو ويدف.\n\nالكويزات : اخذنا نوعين من الكويزات :\n1-interactive quiz: تقريبا كل لاب ناخذ كويز على نفس الي شرحه عشان يختبر معلوماتك. والي حلو انه الكويزات ذي على Kahoot.\n2- كويز واحد وكان عليه 10% من الكورس وهذا الشيئ ماعجبني صراحة لانه النسبة جدا كبيرة وهو اصلا من النوع الي مافيه يسوي كوزات ويبغا يخلص\n\nالمياجر: لايوجد\n\nالفاينلات : فاينل ع البلاكبورد يشمل اخر 5 لابات وكان متنوع من خيارات وصح وخطا واسئلة اجابة قصيرة.\n\nالصوت: واضح بس اللهجة الهندية طاغية وممكن تعاني من الفهم\n\nإضافات : الدكتور صراحة ينفع لاب فقطططط. لانه الريبورتات في الجيب والوضع معاه سهااااالااااات ومايكرف ابدا. راح تاخذ معاه قريد بدون تعب. صراحة افضل دكتور لاب مر علي؛ لاني ابغا قريد صراحة والفهم ممكن افهم من السلايدات. صراحة بطللللللل في اللاب وعن نفسي رح انزل عنده اي مادة لاب.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527548-me323", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-mohammad-anis/98225/21", "user": "Omar_Ali_BajabaaU", "ts": 1609765760000, "tid": 98225, "pn": 21}}]}', 1609765760000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user8551-me323', 'stk-user8551', 'ME 323', 'doc', '{"docs": [{"id": "stk-dr-f98241", "n": "Dr. B. Jabbar Abdul Aleem", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME 323 (Lab) - Term 122\n\nالتحضير : يحضِر و يحضّر بعد 10 دقايق من بداية اللاب ، يدخل المتأخرين و ما يسجل عليهم شئ “يحضرهم عادي” .\n\nالشرح : شرحه بطل ، أرى إنه أفضل من أنور شيخ بمراحل في الشرح (أدرس اللكتشر مع أنور) ، طبعا يشرح بإستخدام سلايدات و سبورة .\nمشكلته إن بعض نقاط الدرس يطوووول بشرحها و باقي النقاط يمر عليهم بسرعة.\nأعطيه 7/10 في الشرح.\n\nالكويزات : ما أعطانا و لا كويز.\n\nالقريدات للريبورتات : يدف بالقريدات ، إكتب الريبورت بنفسك و نسقه بالصور و إطبعه ملون و بيعطيك فوق الـ 9.\nأقل شئ شفته 6 و أعلى شئ 9.8 ، درجات الطلاب متقاربة بشكل عام.\n\nالصوت : واضح ، و اللغة ممتازة.\n\nالقريد النهائي : **+**B\n\nإضافات:\n- دائما متواجد بمكتبه.\n- متساهل مع الطلاب : يسمح بالميك أب ، يأجل تسليم الريبورتات أيام المياجر ، يستلم الريبورتات المتأخرة.\n- اللي يغيب يعطيه صفر باللاب.\n- دائما يشيل بيده ملف mit !\n- يطلع بدري من اللاب.\n\nلي عودة بتفاصيل أكثر مع نهاية الترم إن شاء الله.\n\nكُتب في الأسبوع # 12", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1213420-me323", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-abdul-aleem-b-jabbar/98241/8", "user": "user8551", "ts": 1366454435000, "tid": 98241, "pn": 8}}]}', 1366454435000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-turky_al-dossary-me323', 'stk-turky_al-dossary', 'ME 323', 'doc', '{"docs": [{"id": "stk-dr-f98243", "n": "Dr. Mohammad Raza", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "~~~~ ME- 323 / 206-LAB … Term: 121 ~~~~\n\nالتحضير :\n\nينادي بالاسماء بعد 10 دقايق ،،\n\nطريقة الشرح :\n\nسلايدات وغثيث ،، مسوي انك لازم تسمعها وتفهمها ،، ولا تمسك الجوال ولا تسرح\n\nبس التركيز اللي جبرنا عليه ريحني في الفاينل\n\nالريبورتات :\n\nطبعا قليل اللي يكتب ،، والاكثر ينسخ ،، حاول تنسخ باحتراف لانه يدقق\n\nولا تنسخ من طالب معك في اللاب صفر على الجبهة\n\nيحب تكتب مقدمة وخاتمة قصيرة بس مزبوطه ،، وكثر له كلام وصور في background ،، وامورك طيبة\n\nالفاينلات :\n\nكومن ،، خيارات وصح وخطأ ،، وفراغات\n\nالقريد النهائي:\n\nB\n\nإضافات :\n\nحبيب ،، بس ما يرفع الضغط الا اذا جاء يشرح ،، ما تقدر تمسك الجوال 😲\n\nمجموعي ريبورتات 64 من 75 ،، والفاينل 16 من 25 ،، مجموعي:: 80 وعطاني +B ،، ما كان عندي غيابات\n___________________________________________\n\nاي سؤال ،، لا يردك الا رسالة خاصة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1162354-me323", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-raza/98243/15", "user": "Turky_Al-Dossary", "ts": 1357928466000, "tid": 98243, "pn": 15}}]}', 1357928466000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-amrfa-me323', 'stk-amrfa', 'ME 323', 'doc', '{"docs": [{"id": "stk-dr-f103286", "n": "Dr. Faheemuddin Patel", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME 323 - Term 131\n\nالتحضير بعد نهاية اول ساعة (ساعة الشرح)\n\nشرحه كويس حتى بعض الاحيان افهم منه اشياء ما اكون فهمتها باللكتشر\n\nو تصحيحه للريبورتات يعتبر جامد حبتين و يدقق من ناحية النسخ و خصوصا لو كنت ناسخ من خويك اللي معاك بنفس السكشن. بس حتى لمن كشفني و انا ناقل من واحد اعطاني 7 🙂 ! Not a big deal\n\nصوته مسموع بس الوضوح ممكن 70% بعد التعود 🙂\n\nيسمح انك تحضر طول السمستر مع سكشن تاني , و يسمح انك اذا غبت تسوي ميك أب بس اعطيه عذر زي الناس مو تقوله كنت نايم 🙂 ؟!؟!؟!؟\n\nممكن عيبه الوحيد يطول بالشرح يعني اللاب معاه ياخد ساعة و نص و تلاقي دكتور ثاني ياخد ساعة بنفس اللاب\n\nاذا ما لقيت غيره سجل معاه مقبول", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1316127-me323", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/faheemuddin-patel/103286/9", "user": "amrfa", "ts": 1389018493000, "tid": 103286, "pn": 9}}]}', 1389018493000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mkd-me323', 'stk-mkd', 'ME 323', 'doc', '{"docs": [{"id": "stk-dr-f103286", "n": "Dr. Faheemuddin Patel", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "السمستر والمادة: ME 323 – Term 171\n\nالتعامل:عادي حبيب مع أغلب الطلاب ، شخصيا ما ادري وش السالفة ماخذ مني موقف ولا فيه شي غلط لكنه كان معي غير ، كل ما سألته يجاوب جواب اللي ما وده يشوف وجهك ،السكاشن الثاني كان زي العسل معهم ، انا كنت مع اول سكشن بالاسبوع وما ادري اذا الشي هذا مأثر عليه\n\nالصوت: واضح\n\nالشرح: ما يبيلها شرح لكن كنت اشوفه عادي واللاب غالبا بيكون ممل\n\nالتحضير: بداية الكلاس ، يسمح تحضر بسكشن ثاني لكن على حسب ، قله أول مرة انك بتحضر ميك اب بعدين شف وضع العيال اللي معك هم يقولون له ولا يسحبون ويحضرون مع اللي يبون ( اذا شفت ناس يحضرون باي سكشن من غير ما يقولون سو اللي تبي )\n\nالتصحيح: ما فيه شي يصحح الفاينل كومن ، الريبورتات اذا انت كاتبها وسويت الأشياء اللي يبيها بالضبط بتاخذ درجة ممتازة\n\nلا تتفلسف وتجيب له ريبورت 214 لانه بيخسف فيك ، اتبع الأشياء اللي مكتوبة بالبلاكبورد بالنص وكثر الله خيرك كافي وزيادة\n\nالمياجر والفاينل (الاختبارات بشكل عام): كومن\n\nإضافات: لا تخليه خيارك الأول ، فيه مدرسين ممتازين لكن ناسي أسمائهم الصراحة مالك الا تسأل اللي ماخذين بالسمسترات الماضية\n\nالفاينل ما عندي نصايح له درجتي ما كانت ذاك الزود ، بالتوفيق", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1504944-me323", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/faheemuddin-patel/103286/12", "user": "MKD", "ts": 1547532640000, "tid": 103286, "pn": 12}}]}', 1547532640000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-guest-me323', 'stk-guest', 'ME 323', 'doc', '{"docs": [{"id": "stk-dr-f103286", "n": "Dr. Faheemuddin Patel", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "درسني لاب ME323 ترم 201 ترم كورونا 🤠\n\nالدكتور شريح بمعنى الكلمة ويدرّس من قلب لدرجة ان بعض السلايدات ممكن أي دكتور يشرحها بخمس دقايق وهو يشرحها لك ب 15دقيقة بس عشان يتأكد 100% ان المعلومة وصلت لك بشكل كامل, ممكن البعض يشوفها سلبية لأن اللاب (بعض الاحيان) ممكن يطوّل لكن حنا بالنهاية كطلاب المفروض يهمنا الشرح.\n\nبالنسبة للريبورتات ما أدري اذا بالنهاية يحذف اسوء ريبورت أو لأ لأنه آخر شي عطانا القريد النهائي بدون مايقولنا.\nالدكتور من ناحية التصحيح (دقيق جدا) وصعب تجيب عند الفل مارك بأي ريبورت, الفل مارك عنده تجيب 9.5 اذا مرّه انت بدعت احس يده تحكّه اذا عطى طالب 10\\10 😆 ويطوّل كثييييييييييييرعشان يسلم لك الدرجات.\n\nكان يعطينا كوزات مفاجأة خيارات تقريبا خمس أسئلة بآخر الكلاس على نفس شرح الكلاس نفسه سهلة جدا عشان يعرف اللي مصحصح باللاب ولا اللي ساحب عليه وبالنهاية بيحسبها ضمن الكلاسوورك والتحضير بنهاية الكلاس ينادي بالأسامي\n\nملاحظة: كلامي هذا على كلاسات ( الأون لاين) ممكن بالحضوري وضعه يختلف وبالتوفيق جميعا.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527640-me323", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/faheemuddin-patel/103286/14", "user": "Guest", "ts": 1609886359000, "tid": 103286, "pn": 14}}]}', 1609886359000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-bader_alqahtani-me323', 'stk-bader_alqahtani', 'ME 323', 'doc', '{"docs": [{"id": "stk-dr-f103286", "n": "Dr. Faheemuddin Patel", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME323 Term 203\nالتحضير :\nكنا اون لاين و كان التحضير انك تجي بس اللاب ٢٠٪؜ و مجرد تخش تضمن ال٢٠٪؜ لكن فيه ١٠٪؜ بارتسبيشن يجي في اي وقت ينادي و اذا نادا احد و ما كان موجود نقصه من ال١٠٪؜.\nطريقة الشرح :\nالدكتور يشرح كل سلايدة زي ما قالوا الشباب و يحب يفصل بزيادة عن اللازم و كنا نطول في اللاب لكنه يسوي الي مطلوب منه الوضع عنده مضبوط وما يسلك في الشرح يسوي الي عليه بس صوته على نبرة وحدة و يجيب النوم و الدكتور ما يتعب ما شاء الله يجلس يتكلم لفترة طويلة.\nالكويزات :ما كان فيه كوزات.\nالمياجر:ما كان فيه.\nالفاينلات :كان مشترك بينه و بين انيس و كان سهل بس للاسف ما كان فيه وقت نجهز له ولا الفاينال جا واضح و سهل و كان mcq و fill the blank لو الي اختبر كان يسوي الريبورتات و ما ينقش غالبا ياخذ ٢٠/٣٠.\nالقريد النهائي:اعطيه B+\nالصوت:واضح و على نبرة وحدة طول اللاب.\nإضافات :\nالدكتور يبي الريبورت مكتوب بشكل صح و سوا حركة معنا بحيث محد يقدر يستفيد من ريبورت قديم و يغير الطلبات من A-Z بحيث يخليك غصب تكتبه و ما تقدر تنسخ من الاترام الي قبل و طلباته كانت مرات قليل و مرات وسط و مرات كثير ، فيه شغلة ما عجبتني انه حطوا لنا برنامج سولد وركس اخر لاب و طلاب الصناعية ما اخذوه ولا عندهم خلفية عنه ، تصحيح الدكتور حقاني مرة و ما يحب الفلسفة في الريبورت يبيك تسوي المطلوب منك بشكل مرتب و ممتاز و ما تسلك قريداته في الاخير ما اقدر احكم لان اعرف قريدات زوينه كانت .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1531249-me323", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/faheemuddin-patel/103286/16", "user": "Bader_Alqahtani", "ts": 1629030167000, "tid": 103286, "pn": 16}}]}', 1629030167000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ak-95-me323', 'stk-ak-95', 'ME 323', 'doc', '{"docs": [{"id": "stk-dr-f118639", "n": "Dr. Iqbal Zafar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME-323 term 152\n(lab)\n\nالتحضير :\nورقة تمشي، والوضع تسلييييييك ،طيب جدًا من هاذي الناحية، أحيانا يبدا اللكشر مافي الا واحد او اثنين، ما عنده مشكلة 👍 ، وحتى لو تأخرت نص ساعة تدخل عادي وتحضر ولا يقولك شيء\n\nطريقة الشرح :\nطبعا طبيعة المادة لكشر 50 دقيقة ، يشرح من السلايدات ، ثم تنتقل للاب وتروح مع تكنيشن يشرح لك\n\nالريبورت:\nمتساهل جدًا 👍 ، أتوقع إنه بس يشيك على أهم الأشياء، بعدين يعطيك 8-9-10 ، ما يحقط ولا يدقق\n\nالفاينل:\nكومون ، وصراحة كان صعب شوي ، ومع ذلك أذكر إني ما كنت متأكد من نص الأسئلة ، بس طلعت بقريد ما كنت أحلم فيه 🤪\n\nالقريد النهائي:\nA+++++++++++++\n\nالصوت:\nواضح لكن اللغة لك عليها شوي\n\nإضافات :\nهذا اللي من جد تقول فيه : ( نزل معه وانت مغمض 😁2:) ، لا تفوته", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1454551-me323", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-iqbal-zafar/118639/8", "user": "AK-95", "ts": 1469791833000, "tid": 118639, "pn": 8}}]}', 1469791833000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
